# 2026-11-10: simple character concepts for the spirits with no manually selected hex art.
# 4 simple concepts x 2 general poses = 8 jobs (32 images) per spirit, 8.2, 3:2, Relax, no image prompt.
import json,urllib.request
B='http://127.0.0.1:8787'
def post(p,b): return json.loads(urllib.request.urlopen(urllib.request.Request(B+p,json.dumps(b).encode(),{'content-type':'application/json','origin':B}),timeout=180).read())
SREF='https://s.mj.run/AfKR2qk4FHY https://s.mj.run/q26JOxhBoSI https://s.mj.run/sKLIrmLWwXM https://s.mj.run/J_6O6qfkcaU https://s.mj.run/VnbfkjfD0Mk https://s.mj.run/w3zg_ZPiC_Y https://s.mj.run/KEqPOMNhrRg https://s.mj.run/RVEBGGZxlLM'
PAL={'sun':'white and gold','moon':'indigo, silver and white','Forest':'leaf green, cream and brown','Mountain':'ochre, brown, slate grey and bone','Water':'deep blue, white and silver'}
POSE=['front view, calm, looks at the viewer','three-quarter view, turned a little to the side, a clear expression']
S={
 ('Arcane Spirits','Dawnborn','sun'):['a young traveler, female, 20 years old, short blond hair, a white hooded travel cloak with gold trim, a wooden staff, warm sunrise light','a young wanderer, female, 20 years old, a long golden braid, a simple white tunic and a gold scarf, a small glowing sun charm at her neck','a young pilgrim, male, 20 years old, a white cloak, he holds a lantern shaped like a sun','a girl, 20 years old, with a wide straw hat with a gold ribbon, a white dress, the sunrise behind her'],
 ('Arcane Spirits','Solar Cleric','sun'):['an old priest, male, 55 years old, a white beard, a white and gold robe, hands together in prayer, soft golden light','a priest, male, 40 years old, a shaved head, a gold sun pendant, he holds a small golden book','a priestess, female, 35 years old, a white veil and a gold circlet, she holds a small lamp shaped like a sun','a kind old healer with glasses, a white robe and a gold stole, one glowing hand raised'],
 ('Arcane Spirits','Aurelion','sun'):['a king, male, 45 years old, short golden hair and beard, a simple gold crown, a white and gold royal coat, a calm proud look, a bright sun behind his head','a young king, male, 30 years old, long blond hair, a gold crown, a white cape, one hand raised with a small ball of sunlight','an old king, male, 60 years old, a white beard, a gold crown, a heavy white cloak with a fur collar, a golden sword held in front of him','a king in plain gold armor with a gold crown, a serious face, sunlight from behind'],
 ('Arcane Spirits','Vespera','moon'):['an empress, female, 35 years old, long black hair, a silver crescent crown, a dark indigo dress, pale skin, a calm cold look, a full moon behind her','an empress, female, 35 years old, silver hair, a black dress with a high collar, crescent earrings, she holds a small glowing moon orb','a queen with a dark veil and a silver tiara, violet eyes, a night sky behind her','a queen, female, 30 years old, short black hair, an indigo cloak with silver trim, one hand raised under a crescent moon'],
 ('Forest','Elk Guardian','Forest'):['a large elk with big antlers and moss on its back, calm eyes, soft forest light, an animal','a tall guardian with an elk skull mask and antlers, a green cloak, a wooden shield','a strong man, 40 years old, with a helmet with antlers, bark-brown armor and a wooden shield','a white stag with green leaves on its antlers, an animal'],
 ('Forest','Forest Fairy','Forest'):['a fairy, female, 25 years old, green leaf wings, a crown of white roses, a simple green dress, a gentle smile','a fairy, female, 25 years old, short brown hair, small leaf wings, a flower in her hair, she holds one white rose','a fairy, male, 25 years old, leaf wings, a green tunic, a crown of leaves','a fairy, female, 25 years old, long green hair, translucent green wings, a cream dress, a few small glowing petals'],
 ('Forest','Root Druid','Forest'):['an old druid woman, 60 years old, grey hair with leaves in it, a brown robe, a wooden staff with one flower','a druid, female, 30 years old, a bark-brown hooded cloak, green eyes, a small plant that sprouts in her hands','an old druid man with a long white beard, moss on his shoulders, a wooden staff','a tree-woman with bark skin and leaves for hair, a calm face'],
 ('Forest','Hollowbloom','Forest'):['a forest queen, female, 30 years old, long green hair, a crown of antlers and flowers, a cream dress, a calm look, a few glowing petals','a queen, female, 30 years old, brown hair, a crown of white blossoms, a green royal cloak, she holds one glowing flower','a queen, female, 30 years old, pale blond hair, a flower crown, open hands with a small green light','a tall woman with antlers, a dress of leaves, a soft green glow behind her'],
 ('Mountain','Chained Berserker','Mountain'):['a big warrior, male, 38 years old, wild grey hair, scars, chains around his arms, a fierce shout','a warrior, male, 40 years old, a bone-white beard, a broken chain collar, a large axe on his shoulder','a berserker, female, 30 years old, white braids, chains on her wrists, war paint, a fierce grin','a bald warrior, male, 38 years old, chains crossed over his bare chest, glowing ochre eyes'],
 ('Mountain','Crystal Golem','Mountain'):['a stone golem with one large crystal on its head and glowing eyes, a simple round shape','a golem of grey rock with ochre crystals on its shoulders and one glowing eye','a small friendly golem of stacked stones with a crystal crown','a tall golem of faceted crystal with a calm stone face'],
 ('Mountain','Gate Knight','Mountain'):['a knight in heavy grey stone armor with a closed helmet and a large tower shield shaped like a gate','a knight, male, 40 years old, a grey beard, bronze and stone armor, his helmet under his arm, a big shield','a knight, female, 30 years old, short white hair, slate armor, she holds a large sword shaped like a key','a huge armored guard with a helmet like a castle tower and a glowing visor'],
 ('Mountain','Rune Smith','Mountain'):['a smith, female, 40 years old, hair tied back, a leather apron, one hammer on her shoulder with a glowing rune on it','a smith, male, 45 years old, a big beard, soot on his face, he raises a hammer over a glowing anvil','a young smith, female, 25 years old, goggles on her forehead, she holds glowing tongs','an old smith with a white braided beard, a bronze arm guard, a glowing rune stone in his hand'],
 ('Water','Tide Warden','Water'):['a warrior, male, 35 years old, short dark blue hair, blue scale armor, he holds a trident','a guard, female, 30 years old, long white hair, blue and silver armor, a trident, water spray','a warrior with a blue helmet with fins and a round shield, a calm sea behind','an old sailor warrior, a grey beard, a blue coat, a trident on his shoulder'],
 ('Water','Storm King','Water'):['a king, male, 40 years old, dark blue hair and a short beard, a silver crown, deep blue and gold armor, storm clouds and lightning behind him','a king, male, 45 years old, long white hair, a blue royal coat, a sword that glows, rain','a young king, male, 28 years old, black hair, a silver crown, a blue cape in the wind, a small lightning spark in one hand','an old king, a grey beard, a blue cloak with a fur collar, a crown, a stormy sea behind him'],
}
n=0
for (origin,name,pal),concepts in S.items():
    for c in concepts:
        for pose in POSE:
            text=f'portrait, character icon, zoomed in, {pose}, {c}. Simple clear design with one main effect. Colors: {PAL[pal]}. Adult proportions. --chaos 8 --ar 3:2 --sw 730 --stylize 0 --v 8.2 --no line art, full body'
            r=post('/api/enqueue',{'text':text,'params':'--sref '+SREF,'prefix':'','repeat':1,'mode':'relax','folder':f'assets/spirits/{origin}/{name}/character design','counts':{'imagePrompts':0,'imageReferences':8}})
            assert r.get('added')==1, r
            n+=1
print('queued',n)
